const description: { en: string; ja: string } = {"en":"Three long hawk feathers stand upright side by side, tips up, a narrow white apart. Each has round ends, a shaft that runs out past the quill end with a white line each side, two bars of three shallow white chevrons, and arcs of down round the quill end.","ja":"長い鷹の羽を三枚、先を上にして細い白をあけて並べて立てます。羽の両端は丸く、羽軸は根元の先まで出し、両側に白い線を入れます。浅い白の山形を三本ずつ二か所に入れ、根元の丸みに沿って産毛の線を描きます。"};

export default construction;
